BEGIN;
CREATE SCHEMA reasoning_lab;
REVOKE ALL ON SCHEMA reasoning_lab FROM PUBLIC;
CREATE TABLE reasoning_lab.configurations(id text PRIMARY KEY, version text NOT NULL, config jsonb NOT NULL, collection_enabled boolean NOT NULL DEFAULT false, approval_reference text, approved_at timestamptz, CHECK(NOT collection_enabled OR (approval_reference IS NOT NULL AND approved_at IS NOT NULL)));
CREATE TABLE reasoning_lab.protocols(id text PRIMARY KEY, version text NOT NULL, method text NOT NULL CHECK(method IN ('cartesian','socratic','pragmatist','neutral')), content jsonb NOT NULL);
CREATE TABLE reasoning_lab.question_versions(id text NOT NULL, version text NOT NULL, domain text NOT NULL, pool text NOT NULL CHECK(pool IN ('intervention','pre','post','delayed')), content jsonb NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE reasoning_lab.participants(id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), withdrawn_at timestamptz);
CREATE TABLE reasoning_lab.consent_versions(id text PRIMARY KEY, document text NOT NULL, approval_reference text, approved_at timestamptz);
CREATE TABLE reasoning_lab.consents(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES reasoning_lab.participants ON DELETE CASCADE, version text NOT NULL REFERENCES reasoning_lab.consent_versions, granted boolean NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reasoning_lab.sessions(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES reasoning_lab.participants ON DELETE CASCADE, config_id text NOT NULL REFERENCES reasoning_lab.configurations, implementation text NOT NULL CHECK(implementation IN ('deterministic','llm')), synthetic boolean NOT NULL DEFAULT false, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(id,participant_id));
CREATE TABLE reasoning_lab.assignments(session_id uuid PRIMARY KEY, participant_id uuid NOT NULL, condition text NOT NULL CHECK(condition IN ('cartesian','socratic','pragmatist','neutral')), seed bigint NOT NULL CHECK(seed BETWEEN 0 AND 4294967295), schedule jsonb NOT NULL, assigned_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(session_id,participant_id) REFERENCES reasoning_lab.sessions(id,participant_id) ON DELETE CASCADE);
CREATE TABLE reasoning_lab.responses(id uuid PRIMARY KEY, session_id uuid NOT NULL, participant_id uuid NOT NULL, item_id text NOT NULL, item_version text NOT NULL, phase text NOT NULL CHECK(phase IN ('intervention','pre','post','delayed')), turn smallint NOT NULL CHECK(turn BETWEEN 0 AND 3), response text NOT NULL CHECK(length(response)<=4000), structured_action jsonb NOT NULL, generated_question text NOT NULL, trace jsonb, recorded_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(session_id,participant_id) REFERENCES reasoning_lab.sessions(id,participant_id) ON DELETE CASCADE, FOREIGN KEY(item_id,item_version) REFERENCES reasoning_lab.question_versions(id,version), UNIQUE(session_id,item_id,turn), UNIQUE(id,participant_id), CHECK(phase='intervention' OR turn=0));
CREATE TABLE reasoning_lab.revisions(id uuid PRIMARY KEY, response_id uuid NOT NULL, participant_id uuid NOT NULL, revision_no integer NOT NULL CHECK(revision_no>0), before_state jsonb NOT NULL, after_state jsonb NOT NULL, rationale text NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(response_id,participant_id) REFERENCES reasoning_lab.responses(id,participant_id) ON DELETE CASCADE, UNIQUE(response_id,revision_no));
CREATE TABLE reasoning_lab.ai_invocations(id uuid PRIMARY KEY, session_id uuid NOT NULL, participant_id uuid NOT NULL, item_id text NOT NULL, item_version text NOT NULL, condition text NOT NULL, model_identifier text NOT NULL, model_version text, prompt_version text NOT NULL REFERENCES reasoning_lab.protocols(id), parameters jsonb NOT NULL, input_question text NOT NULL, participant_response text NOT NULL, generated_questions jsonb, input_tokens integer CHECK(input_tokens>=0), output_tokens integer CHECK(output_tokens>=0), latency_ms integer NOT NULL CHECK(latency_ms>=0), error text, recorded_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(session_id,participant_id) REFERENCES reasoning_lab.sessions(id,participant_id) ON DELETE CASCADE, FOREIGN KEY(item_id,item_version) REFERENCES reasoning_lab.question_versions(id,version));
CREATE TABLE reasoning_lab.blind_keys(blind_id uuid PRIMARY KEY, response_id uuid NOT NULL, participant_id uuid NOT NULL, packet_id uuid NOT NULL, FOREIGN KEY(response_id,participant_id) REFERENCES reasoning_lab.responses(id,participant_id) ON DELETE CASCADE);
CREATE TABLE reasoning_lab.evaluations(id uuid PRIMARY KEY, blind_id uuid NOT NULL REFERENCES reasoning_lab.blind_keys ON DELETE CASCADE, rater_id text NOT NULL, criterion text NOT NULL CHECK(criterion IN ('reconstruction','assumptions','consistency','objections','justification','uncertainty','integration','relevance')), rubric_version text NOT NULL, score smallint CHECK(score BETWEEN 0 AND 4), evidence text, rationale text NOT NULL, locked_at timestamptz, recorded_at timestamptz NOT NULL DEFAULT now(), CHECK(score IS NULL OR length(evidence)>0), UNIQUE(blind_id,rater_id,criterion,rubric_version));
CREATE TABLE reasoning_lab.fidelity_reviews(id uuid PRIMARY KEY, session_id uuid NOT NULL, participant_id uuid NOT NULL, rater_id text NOT NULL, protocol_version text NOT NULL, checks jsonb NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(session_id,participant_id) REFERENCES reasoning_lab.sessions(id,participant_id) ON DELETE CASCADE);
CREATE TABLE reasoning_lab.analysis_runs(id uuid PRIMARY KEY, code_commit text NOT NULL, config_id text NOT NULL REFERENCES reasoning_lab.configurations, input_sha256 text NOT NULL, seed bigint NOT NULL, specification jsonb NOT NULL, synthetic boolean NOT NULL, results jsonb NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now());
-- No INSERT/UPDATE policies or public grants: collection is disabled at the database and API boundaries.
DO $$ DECLARE t text; BEGIN
FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='reasoning_lab' LOOP
 EXECUTE format('ALTER TABLE reasoning_lab.%I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('ALTER TABLE reasoning_lab.%I FORCE ROW LEVEL SECURITY',t);
END LOOP; END $$;
REVOKE ALL ON ALL TABLES IN SCHEMA reasoning_lab FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA reasoning_lab FROM PUBLIC;
COMMIT;
